import manifest from '../../data/skillExamProfiles.json'

// ─────────────────────────────────────────────────────────────────────────────
// Read side of the tier 3 exam profile. The data is generated by
// scripts/build-skill-exam-profiles.ts from data/exam-audit — never authored.
//
// A profile is always scoped to a BOARD and a TIER, because those are the two
// things a student actually sits. Never show a Foundation candidate a claim
// derived from Higher papers.
// ─────────────────────────────────────────────────────────────────────────────

export type BareBand = 'never' | 'rarely' | 'sometimes' | 'usually' | 'almost always'

export type SkillExamProfile = {
  skillId: string
  board: string
  tier: string
  parts: number
  marks: number
  papersSeen: number
  papersTotal: number
  markRange: [number, number]
  framing: Record<string, number>
  barePct: number
  bareBand: BareBand
  calc: Record<string, number>
  markSplits: string[]
  chainedPct: number
  traps: string[]
  sufficient: boolean
  /**
   * How many of this skill’s parts were coded for framing.
   *
   * Zero means the papers were never coded for it — NOT that the skill is
   * never asked plainly. Without this the two were indistinguishable, and
   * every OCR and Edexcel skill was being told "you will almost never be
   * told straight out", derived from no evidence at all.
   */
  framingCoded: number
  /** How the answer is given: numeric, expression, draw_plot, show_that… */
  answerForms: Record<string, number>
  /** mastery = the skill on its own; exam = inside a longer question. */
  kinds: Record<string, number>
}

type Manifest = {
  minParts: number
  slices: { board: string; qualification?: string; tier: string; papers: string[]; series: string[]; skillsPresent: number; skillsSufficient: number }[]
  profiles: Record<string, SkillExamProfile>
}

const data = manifest as unknown as Manifest

export type Tier = 'foundation' | 'higher'

/** The audit codes tiers with a capital; the app uses lowercase throughout. */
const auditTier = (tier: Tier) => (tier === 'higher' ? 'Higher' : 'Foundation')

/** Exam boards we hold coded papers for, in display order. */
/**
 * Boards a GCSE student can be shown, in display order.
 *
 * International GCSE slices are excluded. They are a different qualification
 * with its own papers, not another board sitting the same exam, and offering
 * one on a GCSE briefing would scope every claim to the wrong syllabus. The
 * papers stay coded and the profiles stay generated, so serving iGCSE later
 * is a product decision rather than a data one.
 */
export const codedBoards = (): string[] =>
  [...new Set(
    data.slices
      .filter(s => !/international/i.test(s.qualification ?? ''))
      .map(s => s.board),
  )].sort()

export const minParts = () => data.minParts

/**
 * The profile for one skill on one board and tier, or null when we have no
 * coded evidence. Callers must also check `.sufficient` before rendering any
 * claim — a profile below the evidence bar is real data but too thin to say
 * anything true with.
 */
export function getExamProfile(skillId: string, board: string, tier: Tier): SkillExamProfile | null {
  return data.profiles[`${board}|${auditTier(tier)}|${skillId}`] ?? null
}

/** True when there is enough coded evidence to render the panel at all. */
export function hasUsableProfile(skillId: string, board: string, tier: Tier): boolean {
  return getExamProfile(skillId, board, tier)?.sufficient ?? false
}

/** Which papers a slice was built from — shown as provenance under the panel. */
export function sliceProvenance(board: string, tier: Tier) {
  return data.slices.find(s => s.board === board && s.tier === auditTier(tier)) ?? null
}

// ── Phrasing ─────────────────────────────────────────────────────────────────

/**
 * The framing labels as a student would read them. Keys match the `framing`
 * vocabulary in the coded papers.
 *
 * These are the taxonomy's own terms translated out of analyst language —
 * a student reads "more than one way through", not "multi_route".
 */
export const FRAMING_LABELS: Record<string, string> = {
  bare:             'Asked straight out',
  real_world:       'A real-life situation',
  multi_route:      'More than one way through',
  decision_justify: 'Pick an answer, then explain why',
  consequence:      'What happens when something changes',
  given_formula:    'Formula given, you pick the inputs',
  inverse_operand:  'Given the answer, work backwards',
}

/**
 * How the skill is dressed when it is NOT asked outright, phrased as the tail
 * of a sentence ("It will usually be …").
 *
 * Derived from whichever framing dominates rather than assumed. The claim used
 * to hardcode "written as a real-world problem", which is true for proportion
 * but would be a plain falsehood for a skill dominated by multi_route or
 * decision_justify. Returns null when there is nothing but bare framing, so
 * callers can drop the clause instead of inventing one.
 */
function dominantDressing(p: SkillExamProfile): string | null {
  // Every phrase follows "it's", because that is the frame in all four bands
  // that use one ("it's nearly always ___", "most of the time it's ___", and
  // so on). Keep them noun phrases so they slot in without rewriting.
  const PHRASES: Record<string, string> = {
    real_world:       'wrapped up in a real-life situation',
    multi_route:      'a question with more than one way through',
    decision_justify: 'a question where you pick an answer and then explain why',
    consequence:      'a question about what happens when something else changes',
    given_formula:    'a question that hands you the formula and leaves you to fill it in',
    inverse_operand:  'a question that gives you the answer and asks you to work backwards',
  }

  const top = Object.entries(p.framing)
    .filter(([k]) => k !== 'bare')
    .sort((a, b) => b[1] - a[1])[0]

  return top ? (PHRASES[top[0]] ?? null) : null
}

/**
 * The headline sentence about how often the skill is asked plainly.
 *
 * Both halves are derived — the band from the bare percentage, the dressing
 * from the dominant framing — so a newly coded series rewrites this without
 * anyone editing copy. That is the whole point: when the 2025 papers added
 * three bare proportion questions, this moved from "never" to "rarely" on its
 * own. Deliberately not authored per skill.
 */
export function bareClaim(p: SkillExamProfile, skillName: string): string | null {
  // No framing coding, no claim. Every OCR and Edexcel skill used to reach
  // the "never" band here purely because the field was absent, and the page
  // told those students they would "almost never be told straight out" —
  // asserted from nothing. Silence is the honest output.
  if (p.framingCoded === 0) return null
  const lower = skillName.toLowerCase()
  const dressing = dominantDressing(p)
  // "that you're doing proportion" rather than "that a question is about
  // proportion": it is how a teacher actually says it, and it sidesteps the
  // a/an problem that "it's a(n) <skill> question" would create.
  const told = `told straight out that you're doing ${lower}`

  switch (p.bareBand) {
    // Note there is no "never" wording, even at 0%. Absence across a handful
    // of series is not evidence it cannot come up, and a student who then
    // meets one has been badly served. The strongest claim we make is
    // "almost never".
    case 'never':
      return dressing
        ? `You'll almost never be ${told} — it's nearly always ${dressing}.`
        : `You'll almost never be ${told}.`
    case 'rarely':
      return dressing
        ? `You'll only occasionally be ${told}. Most of the time it's ${dressing}.`
        : `You'll only occasionally be ${told}.`
    case 'sometimes':
      return dressing
        ? `Sometimes you'll be ${told}, but more often it's ${dressing}.`
        : `Sometimes you'll be ${told}, but more often you won't.`
    case 'usually':
      return dressing
        ? `Most of the time you'll be ${told}, though now and then it's ${dressing}.`
        : `Most of the time you'll be ${told}.`
    case 'almost always':
      return `You'll nearly always be ${told}, so spotting it isn't the tricky bit.`
  }
}

/** Whether the mark scheme typically chains, phrased for a student. */
export function chainClaim(p: SkillExamProfile): string | null {
  if (p.chainedPct < 25) return null
  const how = p.chainedPct >= 60 ? 'usually' : 'often'
  return `The marks ${how} build on each other, so a slip early on can cost you the ones after it too.`
}

/** Calculator split, phrased. Null when there is no clear lean. */
export function calcClaim(p: SkillExamProfile): string | null {
  const calc = p.calc.calc ?? 0
  const non = p.calc.non_calc ?? 0
  const total = calc + non
  if (total < 3) return null
  if (calc / total >= 0.75) return 'It nearly always turns up on a calculator paper.'
  if (non / total >= 0.75) return 'It nearly always turns up on a non-calculator paper.'
  return 'It turns up on both calculator and non-calculator papers.'
}

/** How an answer is given, as a student would say it. */
const ANSWER_FORM_PHRASES: Record<string, string> = {
  draw_plot:      'drawing or plotting something',
  draw_shape:     'drawing a shape',
  show_that:      'showing that a given answer is right',
  expression:     'an expression rather than a number',
  equation:       'an equation',
  fraction:       'a fraction',
  ratio:          'a ratio',
  coordinate:     'a coordinate',
  table_complete: 'filling in a table',
  exact_surd:     'an exact answer left in surd form',
  ordering:       'putting things in order',
  set_select:     'picking from a set',
  text:           'something written in words',
  free_text:      'something written in words',
}

/** "about a third" and friends, for a share between 0 and 1. */
function roughShare(share: number): string | null {
  if (share >= 0.45) return 'about half'
  if (share >= 0.3) return 'about a third'
  if (share >= 0.2) return 'about a quarter'
  return null
}

/**
 * What the answer line wants — a claim every coded board supports, because
 * `answer_form` is recorded on every part. This is most of what the OCR and
 * Edexcel panels can honestly say: those papers carry no framing, calc or
 * trap coding, so without this they showed marks and little else.
 */
export function answerFormClaim(p: SkillExamProfile): string | null {
  const entries = Object.entries(p.answerForms)
  const total = entries.reduce((s, [, n]) => s + n, 0)
  if (total < 4) return null

  const numeric = p.answerForms.numeric ?? 0
  const others = entries.filter(([k]) => k !== 'numeric').sort((a, b) => b[1] - a[1])
  const [topKey, topCount] = others[0] ?? []
  const topPhrase = topKey ? ANSWER_FORM_PHRASES[topKey] : null
  const topShare = topCount ? topCount / total : 0

  if (numeric / total >= 0.8) return 'The answer is nearly always just a number.'

  const rough = roughShare(topShare)
  if (topPhrase && rough) {
    return `The answer is usually a number, but ${rough} of these ask for ${topPhrase}.`
  }
  if (numeric / total >= 0.5) {
    return 'The answer is usually a number, with the odd one wanting something else.'
  }
  return null
}

/**
 * Whether the skill is the whole question or a step inside a longer one.
 * `kind` is recorded on every coded part, on every board.
 */
export function kindClaim(p: SkillExamProfile): string | null {
  const exam = p.kinds.exam ?? 0
  const mastery = p.kinds.mastery ?? 0
  const total = exam + mastery
  if (total < 4) return null

  const share = exam / total
  if (share >= 0.6) return 'It usually sits inside a longer question rather than standing on its own.'
  if (share >= 0.35) return 'It often sits inside a longer question, not just on its own.'
  if (share <= 0.15) return 'It is nearly always a question in its own right.'
  return null
}

/** Framing counts as sorted display rows, excluding `bare`. */
export function dressedFramings(p: SkillExamProfile): { key: string; label: string; count: number }[] {
  return Object.entries(p.framing)
    .filter(([k]) => k !== 'bare')
    .sort((a, b) => b[1] - a[1])
    .map(([key, count]) => ({ key, label: FRAMING_LABELS[key] ?? key, count }))
}
